package com.readingroom;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class LibraryService {
 private final UserRepository users; private final BookRepository books; private final AuthorRepository authors;
 private final CategoryRepository categories; private final PublisherRepository publishers;
 private final TransactionRepository transactions; private final FineRepository fines;
 private final ReservationRepository reservations; private final SettingRepository settings; private final SessionService sessions; private final NotificationRepository notifications;
 public LibraryService(UserRepository u,BookRepository b,AuthorRepository a,CategoryRepository c,PublisherRepository p,
   TransactionRepository t,FineRepository f,ReservationRepository r,SettingRepository s,SessionService ss,NotificationRepository nr){
  users=u;books=b;authors=a;categories=c;publishers=p;transactions=t;fines=f;reservations=r;settings=s;sessions=ss;notifications=nr;
 }

 public User authenticated(String auth) {
  if(auth==null||!auth.startsWith("Bearer ")) throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Sign in required");
  Integer id=sessions.userId(auth.substring(7));
  return id==null?throwStatus(HttpStatus.UNAUTHORIZED,"Session expired"):users.findById(id).filter(u->"ACTIVE".equals(u.getStatus())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account inactive"));
 }
 private User throwStatus(HttpStatus s,String m){throw new ResponseStatusException(s,m);}
 public void allow(User u,String...roles){for(String role:roles)if(role.equals(u.getRole()))return;throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Your role cannot perform this action");}
 private Map<String,Object> ok(Object data,String message){return Map.of("success",true,"message",message,"data",data==null?Map.of():data);}

 public Map<String,Object> bookList(Map<String,String> q){
  String search=q.getOrDefault("search","").toLowerCase(), category=q.getOrDefault("categoryId","");
  String availability=q.getOrDefault("availability",""); List<Map<String,Object>> all=books.findAll().stream().map(this::bookView)
   .filter(b->search.isBlank()||String.valueOf(b.get("title")).toLowerCase().contains(search)||String.valueOf(b.get("isbn")).toLowerCase().contains(search)||String.valueOf(b.get("authorName")).toLowerCase().contains(search))
   .filter(b->category.isBlank()||String.valueOf(b.get("categoryId")).equals(category))
   .filter(b->availability.isBlank()||("available".equalsIgnoreCase(availability)?num(b.get("availableCopies"))>0:num(b.get("availableCopies"))==0)).toList();
  int page=Math.max(1,integer(q.get("page"),1)), size=Math.min(100,Math.max(1,integer(q.get("pageSize"),25)));
  int from=Math.min(all.size(),(page-1)*size), to=Math.min(all.size(),from+size);
  return ok(Map.of("books",all.subList(from,to),"total",all.size(),"page",page,"pageSize",size),"Books loaded");
 }
 public Map<String,Object> oneBook(Integer id){return ok(bookView(books.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found"))),"Book loaded");}
 @Transactional public Map<String,Object> saveBook(Integer id,Map<String,Object> x){
  Book b=id==null?new Book():books.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found"));
  b.setTitle(str(x,"title",b.getTitle())); b.setIsbn(str(x,"isbn",b.getIsbn())); b.setDescription(str(x,"description",b.getDescription()));
  b.setAuthorId(integer(x.get("authorId"),b.getAuthorId())); b.setCategoryId(integer(x.get("categoryId"),b.getCategoryId())); b.setPublisherId(integer(x.get("publisherId"),b.getPublisherId()));
  b.setPublicationYear(integer(x.get("publicationYear"),b.getPublicationYear())); b.setLanguage(str(x,"language",b.getLanguage()==null?"English":b.getLanguage()));
  int total=Math.max(0,integer(x.get("totalCopies"),b.getTotalCopies()==null?1:b.getTotalCopies()));
  int issued=(b.getTotalCopies()==null?total:b.getTotalCopies())-(b.getAvailableCopies()==null?total:b.getAvailableCopies());
  b.setTotalCopies(total); b.setAvailableCopies(Math.max(0,total-issued)); b.setRackNumber(str(x,"rackNumber",b.getRackNumber())); b.setStatus(b.getAvailableCopies()>0?"AVAILABLE":"UNAVAILABLE");
  return ok(bookView(books.save(b)),id==null?"Book created":"Book updated");
 }
 @Transactional public void deleteBook(Integer id){Book b=books.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found"));try{books.delete(b);}catch(Exception e){throw new ResponseStatusException(HttpStatus.CONFLICT,"This book has circulation history and cannot be deleted");}}
 public List<Map<String,Object>> categoryList(){return categories.findAll().stream().map(c->Map.<String,Object>of("id",c.getId(),"name",c.getName(),"description",safe(c.getDescription()))).toList();}
 public List<Map<String,Object>> authorList(){return authors.findAll().stream().map(a->Map.<String,Object>of("id",a.getId(),"name",a.getName(),"biography",safe(a.getBiography()),"country",safe(a.getCountry()))).toList();}
 public List<Map<String,Object>> publisherList(){return publishers.findAll().stream().map(p->Map.<String,Object>of("id",p.getId(),"name",p.getName(),"email",safe(p.getEmail()),"phone",safe(p.getPhone()),"address",safe(p.getAddress()),"website",safe(p.getWebsite()))).toList();}
 @Transactional public Map<String,Object> saveCategory(Integer id,Map<String,Object> x){Category c=id==null?new Category():categories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Category not found"));String name=str(x,"name",c.getName());if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Category name is required");c.setName(name);c.setDescription(str(x,"description",c.getDescription()));Category saved=categories.save(c);return ok(Map.of("id",saved.getId(),"name",saved.getName(),"description",safe(saved.getDescription())),id==null?"Category created":"Category updated");}
 @Transactional public void deleteCategory(Integer id){Category c=categories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Category not found"));if(books.countByCategoryId(id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This category is used by books and cannot be deleted");categories.delete(c);}
 @Transactional public Map<String,Object> saveAuthor(Integer id,Map<String,Object> x){Author a=id==null?new Author():authors.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Author not found"));String name=str(x,"name",a.getName());if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Author name is required");a.setName(name);a.setBiography(str(x,"biography",a.getBiography()));a.setCountry(str(x,"country",a.getCountry()));Author saved=authors.save(a);return ok(Map.of("id",saved.getId(),"name",saved.getName(),"biography",safe(saved.getBiography()),"country",safe(saved.getCountry())),id==null?"Author created":"Author updated");}
 @Transactional public void deleteAuthor(Integer id){Author a=authors.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Author not found"));if(books.countByAuthorId(id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This author is used by books and cannot be deleted");authors.delete(a);}
 @Transactional public Map<String,Object> savePublisher(Integer id,Map<String,Object> x){Publisher p=id==null?new Publisher():publishers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Publisher not found"));String name=str(x,"name",p.getName());if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Publisher name is required");p.setName(name);p.setAddress(str(x,"address",p.getAddress()));p.setEmail(str(x,"email",p.getEmail()));p.setPhone(str(x,"phone",p.getPhone()));p.setWebsite(str(x,"website",p.getWebsite()));Publisher saved=publishers.save(p);return ok(Map.of("id",saved.getId(),"name",saved.getName(),"address",safe(saved.getAddress()),"email",safe(saved.getEmail()),"phone",safe(saved.getPhone()),"website",safe(saved.getWebsite())),id==null?"Publisher created":"Publisher updated");}
 @Transactional public void deletePublisher(Integer id){Publisher p=publishers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Publisher not found"));if(books.countByPublisherId(id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This publisher is used by books and cannot be deleted");publishers.delete(p);}

 public Map<String,Object> userList(Map<String,String> q){String search=q.getOrDefault("search","").toLowerCase(),role=q.getOrDefault("role","");List<Map<String,Object>> result=users.findAll().stream().filter(u->role.isBlank()||role.equalsIgnoreCase(u.getRole())).filter(u->search.isBlank()||u.getFullName().toLowerCase().contains(search)||u.getEmail().toLowerCase().contains(search)||safe(u.getStudentId()).toLowerCase().contains(search)).map(this::userView).toList();return ok(Map.of("users",result,"total",result.size()),"Users loaded");}
 @Transactional public Map<String,Object> saveUser(Integer id,Map<String,Object> x){
  User u=id==null?new User():users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));
  u.setFullName(str(x,"fullName",u.getFullName()));u.setEmail(str(x,"email",u.getEmail()));u.setPhone(str(x,"phone",u.getPhone()));u.setDepartment(str(x,"department",u.getDepartment()));u.setStudentId(str(x,"studentId",u.getStudentId()));
  String role=str(x,"role",u.getRole());if(!Set.of("ADMIN","LIBRARIAN","STUDENT").contains(role))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");u.setRole(role);
  Object pass=x.get("password");if(id==null&&(pass==null||String.valueOf(pass).length()<8))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Password must contain at least 8 characters");
  if(pass!=null&&!String.valueOf(pass).isBlank())u.setPasswordHash(org.mindrot.jbcrypt.BCrypt.hashpw(String.valueOf(pass),org.mindrot.jbcrypt.BCrypt.gensalt(12)));
  return ok(userView(users.save(u)),id==null?"User created":"User updated");
 }
 @Transactional public void deactivate(Integer id){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));u.setStatus("INACTIVE");users.save(u);}

 @Transactional public Map<String,Object> issue(Map<String,Object> x,User staff){
  Integer uid=integer(x.get("userId"),null),bid=integer(x.get("bookId"),null);User borrower=users.findById(uid==null?-1:uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student not found"));
  if(!"STUDENT".equals(borrower.getRole())||!"ACTIVE".equals(borrower.getStatus()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an active student account");
  Book book=books.findById(bid==null?-1:bid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found"));
  if(book.getAvailableCopies()==null||book.getAvailableCopies()<1)throw new ResponseStatusException(HttpStatus.CONFLICT,"No copies are currently available");
  long active=transactions.findByUserIdOrderByIssueDateDesc(borrower.getId()).stream().filter(t->Set.of("ISSUED","OVERDUE").contains(t.getStatus())).count();
  int limit=settingInt("borrow_limit",5);if(active>=limit)throw new ResponseStatusException(HttpStatus.CONFLICT,"This student has reached the borrowing limit");
  BookTransaction t=new BookTransaction();t.setUserId(borrower.getId());t.setBookId(book.getId());t.setIssuedBy(staff.getId());t.setIssueDate(LocalDate.now());t.setDueDate(LocalDate.now().plusDays(settingInt("loan_days",14)));t.setStatus("ISSUED");
  book.setAvailableCopies(book.getAvailableCopies()-1);book.setStatus(book.getAvailableCopies()==0?"UNAVAILABLE":"AVAILABLE");books.save(book);BookTransaction saved=transactions.save(t);notify(borrower.getId(),"Book issued", "\""+book.getTitle()+"\" is due on "+t.getDueDate()+".","ISSUE",saved.getId(),"TRANSACTION");return ok(transactionView(saved),"Book issued successfully");
 }
 @Transactional public Map<String,Object> returnBook(Integer id,User staff){
  BookTransaction t=transactions.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Transaction not found"));if("RETURNED".equals(t.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This book has already been returned");
  LocalDate now=LocalDate.now();long days=Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(t.getDueDate(),now));
  t.setReturnDate(now);t.setReturnedTo(staff.getId());t.setStatus("RETURNED");transactions.save(t);
  Book b=books.findById(t.getBookId()).orElseThrow();b.setAvailableCopies(Math.min(b.getTotalCopies(),b.getAvailableCopies()+1));b.setStatus("AVAILABLE");books.save(b);
  if(days>0&&fines.findByTransactionId(id).isEmpty()){Fine f=new Fine();f.setTransactionId(id);f.setUserId(t.getUserId());f.setOverdueDays((int)days);f.setAmount(new BigDecimal(days).multiply(new BigDecimal(setting("fine_per_day","2.00"))));f.setPaidAmount(BigDecimal.ZERO);f.setStatus("PENDING");fines.save(f);notify(t.getUserId(),"Overdue fine recorded", "A fine of ₹"+f.getAmount()+" was recorded for returning \""+books.findById(t.getBookId()).map(Book::getTitle).orElse("your book")+"\" late.","FINE",f.getId(),"FINE");}
  notify(t.getUserId(),"Book returned", "Your return has been recorded.","RETURN",t.getId(),"TRANSACTION");
  return ok(Map.of("transaction",transactionView(t),"overdueDays",days,"fine",days>0?new BigDecimal(days).multiply(new BigDecimal(setting("fine_per_day","2.00"))):BigDecimal.ZERO),"Book returned successfully");
 }
 public Map<String,Object> transactionList(Map<String,String> q,User requester){
  List<BookTransaction> items=transactions.findAll().stream().filter(t->requester.getRole().equals("STUDENT")?t.getUserId().equals(requester.getId()):true)
   .filter(t->q.getOrDefault("status","").isBlank()||Arrays.asList(q.get("status").split(",")).contains(t.getStatus())).filter(t->{String s=q.getOrDefault("search","").toLowerCase();return s.isBlank()||transactionText(t).contains(s);}).sorted(Comparator.comparing(BookTransaction::getIssueDate,Comparator.nullsLast(Comparator.reverseOrder()))).toList();
  return ok(Map.of("transactions",items.stream().map(this::transactionView).toList(),"total",items.size()),"Transactions loaded");
 }
 public Map<String,Object> userTransactions(User u){return ok(Map.of("transactions",transactions.findByUserIdOrderByIssueDateDesc(u.getId()).stream().map(this::transactionView).toList()),"Transactions loaded");}

 public Map<String,Object> settingsView(){Map<String,Object> values=new LinkedHashMap<>();settings.findAll().forEach(s->values.put(s.getKey(),s.getValue()));return ok(values,"Settings loaded");}
 @Transactional public Map<String,Object> updateSetting(String key,String value){LibrarySetting s=settings.findByKey(key).orElseGet(LibrarySetting::new);s.setKey(key);s.setValue(value);settings.save(s);return ok(Map.of("key",key,"value",value),"Setting updated");}
 public Map<String,Object> dashboardAdmin(){List<Book> bs=books.findAll();List<User> us=users.findAll();long issued=transactions.countByStatusIn(List.of("ISSUED","OVERDUE"));long overdue=transactions.findAll().stream().filter(t->Set.of("ISSUED","OVERDUE").contains(t.getStatus())&&t.getDueDate().isBefore(LocalDate.now())).count();BigDecimal pending=fines.findAll().stream().filter(f->Set.of("PENDING","PARTIALLY_PAID").contains(f.getStatus())).map(f->f.getAmount().subtract(f.getPaidAmount()==null?BigDecimal.ZERO:f.getPaidAmount())).reduce(BigDecimal.ZERO,BigDecimal::add);
  Map<String,Object> stats=Map.of("totalBooks",bs.stream().mapToInt(b->n(b.getTotalCopies())).sum(),"availableBooks",bs.stream().mapToInt(b->n(b.getAvailableCopies())).sum(),"issuedBooks",issued,"overdueBooks",overdue,"totalStudents",us.stream().filter(u->"STUDENT".equals(u.getRole())&&"ACTIVE".equals(u.getStatus())).count(),"activeReservations",reservations.countByStatus("ACTIVE"),"pendingFines",pending);
  Map<Integer,Long> grouped=new HashMap<>();bs.forEach(b->grouped.merge(b.getCategoryId(),1L,Long::sum));List<Map<String,Object>> categoriesData=grouped.entrySet().stream().map(e->Map.<String,Object>of("name",categories.findById(e.getKey()).map(Category::getName).orElse("Other"),"value",e.getValue())).toList();
  return ok(Map.of("stats",stats,"charts",Map.of("categoryDistribution",categoriesData,"monthlyIssuesReturns",List.of()),"recentTransactions",transactions.findAll().stream().sorted(Comparator.comparing(BookTransaction::getIssueDate,Comparator.nullsLast(Comparator.reverseOrder()))).limit(8).map(this::transactionView).toList()),"Dashboard loaded");
 }
 public Map<String,Object> dashboardStudent(User u){List<BookTransaction> current=transactions.findByUserIdOrderByIssueDateDesc(u.getId()).stream().filter(t->Set.of("ISSUED","OVERDUE").contains(t.getStatus())).toList();List<Fine> userFines=fines.findByUserId(u.getId());long overdue=current.stream().filter(t->t.getDueDate().isBefore(LocalDate.now())).count();long due=current.stream().filter(t->!t.getDueDate().isBefore(LocalDate.now())&&!t.getDueDate().isAfter(LocalDate.now().plusDays(3))).count();BigDecimal amount=userFines.stream().filter(f->Set.of("PENDING","PARTIALLY_PAID").contains(f.getStatus())).map(f->f.getAmount().subtract(f.getPaidAmount()==null?BigDecimal.ZERO:f.getPaidAmount())).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object> stats=Map.of("activeBorrows",current.size(),"dueSoon",due,"overdue",overdue,"pendingFines",amount);return ok(Map.of("stats",stats,"currentBorrows",current.stream().map(this::transactionView).toList(),"activeReservations",reservations.findByUserIdOrderByCreatedAtDesc(u.getId()).stream().filter(r->"ACTIVE".equals(r.getStatus())).map(this::reservationView).toList()),"Dashboard loaded");}
 @Transactional public Map<String,Object> reserve(Integer bookId,User user){Book b=books.findById(bookId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found"));if(b.getAvailableCopies()>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This book is available to borrow now");if(reservations.existsByUserIdAndBookIdAndStatus(user.getId(),bookId,"ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"You already reserved this book");Reservation r=new Reservation();r.setUserId(user.getId());r.setBookId(bookId);r.setStatus("ACTIVE");r.setCreatedAt(LocalDateTime.now());r.setExpiresAt(r.getCreatedAt().plusDays(settingInt("reservation_expiry_days",7)));Reservation saved=reservations.save(r);notify(user.getId(),"Reservation placed", "You’ll be notified when \""+b.getTitle()+"\" is available.","RESERVATION",saved.getId(),"RESERVATION");return ok(reservationView(saved),"Book reserved");}
 public Map<String,Object> reservationList(User user){List<Reservation> list=user.getRole().equals("STUDENT")?reservations.findByUserIdOrderByCreatedAtDesc(user.getId()):reservations.findAll();return ok(Map.of("reservations",list.stream().map(this::reservationView).toList()),"Reservations loaded");}
 @Transactional public void cancelReservation(Integer id,User user){Reservation r=reservations.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Reservation not found"));if(user.getRole().equals("STUDENT")&&!r.getUserId().equals(user.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your reservation");r.setStatus("CANCELLED");reservations.save(r);}

 public List<Map<String,Object>> fineList(User user){List<Fine> items=user.getRole().equals("STUDENT")?fines.findByUserId(user.getId()):fines.findAll();return items.stream().map(f->Map.<String,Object>of("id",f.getId(),"amount",f.getAmount(),"paidAmount",f.getPaidAmount()==null?BigDecimal.ZERO:f.getPaidAmount(),"overdueDays",n(f.getOverdueDays()),"status",f.getStatus(),"transaction",transactionView(transactions.findById(f.getTransactionId()).orElseThrow()))).toList();}
 public List<Map<String,Object>> recommendationList(User user){Set<Integer> borrowed=transactions.findByUserIdOrderByIssueDateDesc(user.getId()).stream().map(BookTransaction::getBookId).collect(java.util.stream.Collectors.toSet());Map<Integer,Long> preferences=new HashMap<>();transactions.findByUserIdOrderByIssueDateDesc(user.getId()).forEach(t->books.findById(t.getBookId()).ifPresent(b->{if(b.getCategoryId()!=null)preferences.merge(b.getCategoryId(),1L,Long::sum);}));List<Book> picks=books.findAll().stream().filter(b->!borrowed.contains(b.getId())&&n(b.getAvailableCopies())>0).sorted(Comparator.<Book>comparingLong(b->preferences.getOrDefault(b.getCategoryId(),0L)).reversed().thenComparing(Book::getTitle)).limit(12).toList();return picks.stream().map(this::bookView).toList();}
 public List<Map<String,Object>> mostBorrowed(){Map<Integer,Long> counts=new HashMap<>();transactions.findAll().forEach(t->counts.merge(t.getBookId(),1L,Long::sum));return counts.entrySet().stream().sorted(Map.Entry.<Integer,Long>comparingByValue().reversed()).limit(50).map(e->{Map<String,Object> row=new LinkedHashMap<>();row.put("book",books.findById(e.getKey()).map(this::bookView).orElse(Map.of()));row.put("borrowCount",e.getValue());return row;}).toList();}
 public List<Map<String,Object>> overdueTransactions(){return transactions.findAll().stream().filter(t->Set.of("ISSUED","OVERDUE").contains(t.getStatus())&&t.getDueDate()!=null&&t.getDueDate().isBefore(LocalDate.now())).map(this::transactionView).toList();}
 public Map<String,Object> notificationList(User u){List<Notification> list=notifications.findByUserIdOrderByCreatedAtDesc(u.getId());return ok(Map.of("notifications",list.stream().map(this::notificationView).toList(),"unreadCount",notifications.countByUserIdAndReadFalse(u.getId())),"Notifications loaded");}
 @Transactional public void markNotificationRead(Integer id,User u){Notification item=notifications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found"));if(!item.getUserId().equals(u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your notification");item.setRead(true);notifications.save(item);}
 @Transactional public void markAllNotificationsRead(User u){notifications.findByUserIdOrderByCreatedAtDesc(u.getId()).forEach(n->{if(!n.isRead())n.setRead(true);});}
 private void notify(Integer userId,String title,String message,String type,Integer referenceId,String referenceType){Notification n=new Notification();n.setUserId(userId);n.setTitle(title);n.setMessage(message);n.setType(type);n.setReferenceId(referenceId);n.setReferenceType(referenceType);n.setRead(false);n.setCreatedAt(LocalDateTime.now());notifications.save(n);}
 private Map<String,Object> notificationView(Notification n){return Map.of("id",n.getId(),"title",n.getTitle(),"message",n.getMessage(),"type",n.getType(),"read",n.isRead(),"createdAt",String.valueOf(n.getCreatedAt()));}

 private Map<String,Object> bookView(Book b){Map<String,Object> m=new LinkedHashMap<>();m.put("id",b.getId());m.put("isbn",safe(b.getIsbn()));m.put("title",b.getTitle());m.put("description",safe(b.getDescription()));m.put("authorId",b.getAuthorId());m.put("categoryId",b.getCategoryId());m.put("publisherId",b.getPublisherId());m.put("author",b.getAuthorId()==null?null:authors.findById(b.getAuthorId()).map(a->Map.of("id",a.getId(),"name",a.getName())).orElse(null));m.put("category",b.getCategoryId()==null?null:categories.findById(b.getCategoryId()).map(c->Map.of("id",c.getId(),"name",c.getName())).orElse(null));m.put("publisher",b.getPublisherId()==null?null:publishers.findById(b.getPublisherId()).map(p->Map.of("id",p.getId(),"name",p.getName())).orElse(null));m.put("authorName",b.getAuthorId()==null?"":authors.findById(b.getAuthorId()).map(Author::getName).orElse(""));m.put("categoryName",b.getCategoryId()==null?"":categories.findById(b.getCategoryId()).map(Category::getName).orElse(""));m.put("publisherName",b.getPublisherId()==null?"":publishers.findById(b.getPublisherId()).map(Publisher::getName).orElse(""));m.put("publicationYear",b.getPublicationYear());m.put("language",safe(b.getLanguage()));m.put("totalCopies",n(b.getTotalCopies()));m.put("availableCopies",n(b.getAvailableCopies()));m.put("rackNumber",safe(b.getRackNumber()));m.put("status",safe(b.getStatus()));return m;}
 private Map<String,Object> userView(User u){Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.getId());m.put("fullName",u.getFullName());m.put("email",u.getEmail());m.put("phone",safe(u.getPhone()));m.put("role",u.getRole());m.put("department",safe(u.getDepartment()));m.put("studentId",safe(u.getStudentId()));m.put("status",u.getStatus());m.put("isActive","ACTIVE".equals(u.getStatus()));return m;}
 private Map<String,Object> transactionView(BookTransaction t){Map<String,Object> m=new LinkedHashMap<>();m.put("id",t.getId());m.put("userId",t.getUserId());m.put("bookId",t.getBookId());m.put("user",users.findById(t.getUserId()).map(u->Map.of("id",u.getId(),"fullName",u.getFullName(),"email",u.getEmail())).orElse(Map.of()));m.put("book",books.findById(t.getBookId()).map(this::bookView).orElse(Map.of()));m.put("issueDate",t.getIssueDate());m.put("dueDate",t.getDueDate());m.put("returnDate",t.getReturnDate());m.put("status",t.getStatus());long overdueDays=Set.of("ISSUED","OVERDUE").contains(t.getStatus())&&t.getDueDate()!=null?Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(t.getDueDate(),LocalDate.now())):0;m.put("finePreview",new BigDecimal(overdueDays).multiply(new BigDecimal(setting("fine_per_day","2.00"))));return m;}
 private Map<String,Object> reservationView(Reservation r){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getId());m.put("userId",r.getUserId());m.put("user",users.findById(r.getUserId()).map(u->Map.of("id",u.getId(),"fullName",u.getFullName(),"email",u.getEmail())).orElse(Map.of()));m.put("bookId",r.getBookId());m.put("book",books.findById(r.getBookId()).map(this::bookView).orElse(Map.of()));m.put("status",r.getStatus());m.put("createdAt",String.valueOf(r.getCreatedAt()));m.put("expiresAt",r.getExpiresAt()==null?null:String.valueOf(r.getExpiresAt()));return m;}
 private String transactionText(BookTransaction t){return (users.findById(t.getUserId()).map(u->u.getFullName()+" "+u.getEmail()).orElse("")+" "+books.findById(t.getBookId()).map(Book::getTitle).orElse("")).toLowerCase();}
 private int settingInt(String k,int d){try{return Integer.parseInt(setting(k,String.valueOf(d)));}catch(Exception e){return d;}}
 private String setting(String k,String d){return settings.findByKey(k).map(LibrarySetting::getValue).filter(v->v!=null&&!v.isBlank()).orElse(d);}
 private static int n(Integer v){return v==null?0:v;} private static int num(Object v){return v instanceof Number n?n.intValue():0;}
 private static int integer(Object v,Integer fallback){if(v==null||String.valueOf(v).isBlank())return fallback==null?0:fallback;try{return Integer.parseInt(String.valueOf(v));}catch(Exception e){return fallback==null?0:fallback;}}
 private static String str(Map<String,Object> m,String k,String fallback){Object v=m.get(k);return v==null?fallback:String.valueOf(v);}
 private static String safe(String s){return s==null?"":s;}
}
